`timescale 1ns/1ps

// ============================================================================
// target_track.v  (patch_v2)
//   target_detect   : colour target detection on the camera image
//   target_overlay  : box + cross + text (name / colour / coordinates) on the output
//   bin2bcd_seq     : small sequential binary -> BCD converter for the coordinate text
// Generated by gen_target_track.py (glyph ROM included).  ASCII only.
// ============================================================================


// ----------------------------------------------------------------------------
// Colour target detection.
//   A pixel "hits" when the selected colour dominates the other channels by DIFF.
//   Only pixels that follow at least RUN_MIN-1 consecutive hits on the same line
//   are counted ("qualified"), which removes isolated noise pixels.
//   Qualified pixels build a bounding box and a pixel count over one frame; at the
//   next vsync the result is latched and kept for the whole following frame.
//   color_sel: 0 red, 1 green, 2 blue, 3 yellow.
//   dir      : 0 not found, 1 left, 2 right, 3 centre (relative to CENTER_X +- DEAD_X).
// ----------------------------------------------------------------------------
module target_detect #(
    parameter integer RUN_MIN     = 6,
    parameter integer MIN_COUNT   = 300,
    parameter integer DIFF        = 48,
    parameter integer MIN_LEVEL   = 60,
    parameter integer HOLD_FRAMES = 3,
    parameter integer CENTER_X    = 624,
    parameter integer DEAD_X      = 96
)(
    input  wire        clk,
    input  wire        rst_n,
    input  wire        in_vs,
    input  wire        in_hs,
    input  wire        in_de,
    input  wire [23:0] in_rgb,
    input  wire        in_win,        // pixel belongs to the camera image window
    input  wire [1:0]  color_sel,
    output reg         found,
    output reg  [10:0] x0,
    output reg  [10:0] x1,
    output reg  [9:0]  y0,
    output reg  [9:0]  y1,
    output reg  [10:0] cx,
    output reg  [9:0]  cy,
    output reg  [1:0]  dir,
    output reg  [19:0] cnt_pub,       // qualified pixel count of the published frame (used for shape)
    output reg  [19:0] cnt_top_pub,   // ... of which in the upper half (y <= previous centre y), used to tell a triangle from a rotated square
    output reg  [19:0] cnt_left_pub,  // ... of which in the left half (x <= previous centre x)
    output reg         upd            // one-cycle pulse when a new result has been latched
);

    reg [10:0] x;
    reg [9:0]  y;
    reg        vs_d;
    reg        hs_d;
    reg        line_has_de;

    wire [7:0] r = in_rgb[23:16];
    wire [7:0] g = in_rgb[15:8];
    wire [7:0] b = in_rgb[7:0];
    wire [8:0] r9 = {1'b0, r};
    wire [8:0] g9 = {1'b0, g};
    wire [8:0] b9 = {1'b0, b};

    // Brightness-relative colour rules: the required margin is a third of the pixel's own brightest channel
    // (at least 28), so dim and bright objects are judged alike and a global cast hurts less.
    wire [8:0] mx_rg = (r9 > g9) ? r9 : g9;
    wire [8:0] mx_all = (mx_rg > b9) ? mx_rg : b9;
    wire [8:0] mgn_all = (mx_all[8:2] + mx_all[8:4] > 9'd28) ? (mx_all[8:2] + mx_all[8:4]) : 9'd28; // ~5/16 of peak
    wire [8:0] mn_rg = (r9 < g9) ? r9 : g9;
    wire [8:0] mn_rb = (r9 < b9) ? r9 : b9;
    wire [8:0] mn_gb = (g9 < b9) ? g9 : b9;
    wire is_red    = (r >= MIN_LEVEL) && (r9 >= g9 + mgn_all) && (r9 >= b9 + mgn_all);
    wire is_green  = (g >= MIN_LEVEL) && (g9 >= r9 + mgn_all) && (g9 >= b9 + mgn_all);
    wire is_blue   = (b >= MIN_LEVEL) && (b9 >= r9 + mgn_all) && (b9 >= g9 + mgn_all);
    wire is_yellow = (r >= MIN_LEVEL) && (g >= MIN_LEVEL) &&
                     (r9 >= b9 + mgn_all) && (g9 >= b9 + mgn_all) &&
                     (r9 < g9 + mgn_all) && (g9 < r9 + mgn_all);

    reg match;
    always @(*) begin
        case(color_sel)
            2'd0:    match = is_red;
            2'd1:    match = is_green;
            2'd2:    match = is_blue;
            default: match = is_yellow;
        endcase
    end

    reg y_ovf;   // 1080p: y is 10 bit, lines >= 1024 are ignored
    wire hit = in_de && in_win && match && !y_ovf;

    reg [3:0] run;
    wire      qual = hit && (run >= RUN_MIN - 1);
    wire      qual_box = hit && (run >= 4'd11);

    reg [19:0] cnt;
    reg [19:0] cnt_top;
    reg [19:0] cnt_left;
    reg [10:0] axmin;
    reg [10:0] axmax;
    reg [9:0]  aymin;
    reg [9:0]  aymax;
    reg [1:0]  miss;

    wire [10:0] x_start = x - (RUN_MIN - 1);
    wire [11:0] sumx    = {1'b0, axmin} + {1'b0, axmax};
    wire [10:0] sumy    = {1'b0, aymin} + {1'b0, aymax};
    wire [10:0] cx_new  = sumx[11:1];
    wire [9:0]  cy_new  = sumy[10:1];

    always @(posedge clk or negedge rst_n) begin
        if(!rst_n) begin
            x <= 11'd0;
            y <= 10'd0;
            vs_d <= 1'b0;
            hs_d <= 1'b0;
            line_has_de <= 1'b0;
            y_ovf <= 1'b0;
            run <= 4'd0;
            cnt <= 20'd0;
            axmin <= 11'h7FF;
            axmax <= 11'd0;
            aymin <= 10'h3FF;
            aymax <= 10'd0;
            miss <= 2'd0;
            found <= 1'b0;
            x0 <= 11'd0;
            x1 <= 11'd0;
            y0 <= 10'd0;
            y1 <= 10'd0;
            cx <= 11'd0;
            cy <= 10'd0;
            dir <= 2'd0;
            cnt_pub <= 20'd0;
            cnt_top_pub <= 20'd0;
            cnt_top <= 20'd0;
            cnt_left_pub <= 20'd0;
            cnt_left <= 20'd0;
            upd <= 1'b0;
        end
        else begin
            vs_d <= in_vs;
            hs_d <= in_hs;
            upd  <= 1'b0;

            // pixel / line position (y is 0 on the first active line)
            if(in_vs && !vs_d) begin
                x <= 11'd0;
                y <= 10'd0;
                y_ovf <= 1'b0;
                line_has_de <= 1'b0;
            end
            else if(!in_hs && hs_d) begin
                x <= 11'd0;
                if(line_has_de) begin
                    y <= y + 10'd1;
                    if(y == 10'h3FF) y_ovf <= 1'b1;
                end
                line_has_de <= 1'b0;
            end
            else if(in_de) begin
                x <= x + 11'd1;
                line_has_de <= 1'b1;
            end

            // run of consecutive hits on the current line
            if(hit)
                run <= (run == 4'd15) ? 4'd15 : (run + 4'd1);
            else
                run <= 4'd0;

            if(in_vs && !vs_d) begin
                // frame finished: publish the result and restart the accumulators
                if(cnt >= MIN_COUNT && axmax >= axmin) begin
                    found <= 1'b1;
                    x0 <= axmin;
                    x1 <= axmax;
                    y0 <= aymin;
                    y1 <= aymax;
                    cx <= cx_new;
                    cy <= cy_new;
                    cnt_pub <= cnt;
                    cnt_top_pub <= cnt_top;
                    cnt_left_pub <= cnt_left;
                    miss <= 2'd0;
                    if(cx_new + DEAD_X < CENTER_X)
                        dir <= 2'd1;
                    else if(cx_new > CENTER_X + DEAD_X)
                        dir <= 2'd2;
                    else
                        dir <= 2'd3;
                end
                else if(found && (miss < HOLD_FRAMES)) begin
                    miss <= miss + 2'd1;      // keep the last result for a few frames
                end
                else begin
                    found <= 1'b0;
                    dir <= 2'd0;
                end
                upd <= 1'b1;
                cnt <= 20'd0;
                cnt_top <= 20'd0;
                cnt_left <= 20'd0;
                axmin <= 11'h7FF;
                axmax <= 11'd0;
                aymin <= 10'h3FF;
                aymax <= 10'd0;
            end
            else if(qual) begin
                cnt <= cnt + 20'd1;
                if({1'b0, y} <= {1'b0, cy}) cnt_top <= cnt_top + 20'd1;
                if({1'b0, x} <= {1'b0, cx}) cnt_left <= cnt_left + 20'd1;
                if(qual_box && (x - 11'd11) < axmin) axmin <= x - 11'd11;
                if(qual_box && x > axmax) axmax <= x;
                if(qual_box && y < aymin) aymin <= y;
                if(qual_box && y > aymax) aymax <= y;
            end
        end
    end

endmodule


// ----------------------------------------------------------------------------
// Shape classification from the fill ratio of the bounding box:
//   pct = 100 * qualified_pixels / (box_width * box_height)
//   rectangle ~ 95, circle ~ 74 (pi/4 minus edge loss), triangle ~ 47 (about half).
//   shape: 0 rectangle (pct >= T_RECT), 1 circle (pct >= T_CIRC), 2 triangle.
//   conf : 100 - 2 * |pct - ideal| of the chosen shape, clipped to 0..100 (a match score).
// Sequential (about 30 clocks): start with the box and cnt valid, done pulses when shape/conf are updated.
// ----------------------------------------------------------------------------
module shape_classify #(
    parameter integer T_RECT = 78,
    parameter integer T_CIRC = 60,
    parameter integer I_RECT = 88,
    parameter integer I_CIRC = 74,
    parameter integer I_TRI  = 47
)(
    input  wire        clk,
    input  wire        rst_n,
    input  wire        start,
    input  wire [10:0] x0,
    input  wire [10:0] x1,
    input  wire [9:0]  y0,
    input  wire [9:0]  y1,
    input  wire [19:0] cnt,
    input  wire [19:0] cnt_top,
    input  wire [19:0] cnt_left,
    output reg  [1:0]  shape,
    output reg  [6:0]  conf,
    output reg         done
);
    reg [2:0]  st;
    reg [20:0] area;
    reg [26:0] num;
    reg [26:0] rem;
    reg [26:0] quo;
    reg [4:0]  it;
    reg [26:0] rem_n;
    reg [26:0] quo_n;
    reg [10:0] w;
    reg [9:0]  h;
    reg [8:0]  pct;
    reg [8:0]  ideal;
    reg [8:0]  diff;
    reg [9:0]  pen;

    // a triangle has most of its pixels on one side of one of the centre lines, a rotated square (fill ~50 %) is balanced on both
    wire [23:0] t10 = {cnt_top, 3'b000} + {cnt_top, 1'b0};
    wire [23:0] c4  = {2'b00, cnt, 2'b00};
    wire [23:0] c6  = {2'b00, cnt, 2'b00} + {3'b000, cnt, 1'b0};
    wire [23:0] l10 = {cnt_left, 3'b000} + {cnt_left, 1'b0};
    // balanced about BOTH the horizontal and the vertical centre line (a triangle is never balanced about both)
    wire        sym = (t10 >= c4) && (t10 <= c6) && (l10 >= c4) && (l10 <= c6);

    always @(posedge clk or negedge rst_n) begin
        if(!rst_n) begin
            st <= 3'd0; area <= 21'd0; num <= 27'd0; rem <= 27'd0; quo <= 27'd0; it <= 5'd0;
            w <= 11'd0; h <= 10'd0; pct <= 9'd0; ideal <= 9'd0; diff <= 9'd0; pen <= 10'd0;
            shape <= 2'd0; conf <= 7'd0; done <= 1'b0;
        end
        else begin
            done <= 1'b0;
            case(st)
                3'd0: if(start) begin
                    w <= x1 - x0 + 11'd1;
                    h <= y1 - y0 + 10'd1;
                    st <= 3'd1;
                end
                3'd1: begin
                    area <= w * h;
                    num  <= cnt * 7'd100;
                    rem  <= 27'd0;
                    quo  <= 27'd0;
                    it   <= 5'd0;
                    st   <= 3'd2;
                end
                3'd2: begin
                    // restoring division, one bit per clock, 27 bits
                    rem_n = {rem[25:0], num[26]};
                    quo_n = {quo[25:0], 1'b0};
                    if(rem_n >= {6'd0, area}) begin
                        rem_n = rem_n - {6'd0, area};
                        quo_n[0] = 1'b1;
                    end
                    rem <= rem_n;
                    quo <= quo_n;
                    num <= {num[25:0], 1'b0};
                    it  <= it + 5'd1;
                    if(it == 5'd26) st <= 3'd3;
                end
                3'd3: begin
                    pct <= (quo > 27'd127) ? 9'd127 : quo[8:0];
                    st  <= 3'd4;
                end
                3'd4: begin
                    if(pct >= T_RECT) begin
                        shape <= 2'd0; ideal <= I_RECT;
                    end
                    else if(pct >= T_CIRC) begin
                        shape <= 2'd1; ideal <= I_CIRC;
                    end
                    else if(sym) begin
                        shape <= 2'd0; ideal <= 9'd50;     // balanced halves, low fill: rotated rectangle
                    end
                    else begin
                        shape <= 2'd2; ideal <= I_TRI;
                    end
                    st <= 3'd5;
                end
                3'd5: begin
                    diff <= (pct > ideal) ? (pct - ideal) : (ideal - pct);
                    st <= 3'd6;
                end
                3'd6: begin
                    pen <= {diff, 1'b0};
                    st <= 3'd7;
                end
                default: begin
                    conf <= (pen >= 10'd100) ? 7'd0 : (7'd100 - pen[6:0]);
                    done <= 1'b1;
                    st <= 3'd0;
                end
            endcase
        end
    end
endmodule


// ----------------------------------------------------------------------------
// Sequential binary -> BCD (double dabble).  Loads on start, W clocks later bcd is valid.
// ----------------------------------------------------------------------------
module bin2bcd_seq #(
    parameter integer W = 11,
    parameter integer D = 4
)(
    input  wire           clk,
    input  wire           rst_n,
    input  wire           start,
    input  wire [W-1:0]   bin,
    output reg  [4*D-1:0] bcd
);
    reg [4*D+W-1:0] sh;
    reg [4*D+W-1:0] adj;
    reg [4*D+W-1:0] nxt;
    reg [4:0]       cnt;
    reg             busy;
    integer         i;

    always @(posedge clk or negedge rst_n) begin
        if(!rst_n) begin
            sh   <= 0;
            cnt  <= 5'd0;
            busy <= 1'b0;
            bcd  <= 0;
        end
        else if(start) begin
            sh   <= {{(4*D){1'b0}}, bin};
            cnt  <= 5'd0;
            busy <= 1'b1;
        end
        else if(busy) begin
            adj = sh;
            for(i = 0; i < D; i = i + 1) begin
                if(adj[W + 4*i +: 4] > 4'd4)
                    adj[W + 4*i +: 4] = adj[W + 4*i +: 4] + 4'd3;
            end
            nxt = adj << 1;
            sh  <= nxt;
            cnt <= cnt + 5'd1;
            if(cnt == W - 1) begin
                busy <= 1'b0;
                bcd  <= nxt[W +: 4*D];
            end
        end
    end
endmodule


// ----------------------------------------------------------------------------
// Overlay: bounding box, cross at the centre, and a line of text at (TXT_X, TXT_Y):
//   found     :  [target]:[colour][se]  X:xxxx  Y:yyy
//   not found :  [no target found]
// glyph ids: 0 blank, 1..13 text, 16..25 digits 0..9 (see ROM below).
// ----------------------------------------------------------------------------
module target_overlay #(
    parameter integer TXT_X = 32,
    parameter integer TXT_Y = 62,
    parameter integer LAT_X = 336,    // latency text "[delay]:xxxms", 8 characters wide
    parameter integer STAT_X  = 336,  // brightness read-out, 19 characters wide
    parameter integer STAT_Y0 = 6,    // line 1: P R:xxx G:xxx B:xxx   (before the digital gain)
    parameter integer STAT_Y1 = 30    // line 2:   R:xxx G:xxx B:xxx   (after the digital gain, what is displayed)
)(
    input  wire        clk,
    input  wire        rst_n,
    input  wire        in_vs,
    input  wire        in_hs,
    input  wire        in_de,
    input  wire [23:0] in_rgb,
    input  wire        enable,
    input  wire        found,
    input  wire [10:0] x0,
    input  wire [10:0] x1,
    input  wire [9:0]  y0,
    input  wire [9:0]  y1,
    input  wire [10:0] cx,
    input  wire [9:0]  cy,
    input  wire [1:0]  color_sel,
    input  wire        upd,
    input  wire [1:0]  shape,         // 0 rectangle, 1 circle, 2 triangle
    input  wire [6:0]  conf,          // match score 0..100
    input  wire        shape_upd,
    input  wire        lat_enable,    // show the latency text (independent of enable)
    input  wire [9:0]  lat_ms,
    input  wire        mot_enable,    // motion detection mode: show the motion line
    input  wire [12:0] mot_cnt,       // moving blocks in the last frame
    input  wire [13:0] mot_ev,        // motion events
    input  wire        mot_upd,
    input  wire        lat_upd,
    input  wire [13:0] frm_cnt,
    input  wire [7:0]  fper,
    input  wire [13:0] foc_score,     // focus meter: sharpness value
    input  wire [6:0]  foc_bar,       // focus meter: bar length relative to the recent peak (0..127)
    input  wire        foc_upd,
    input  wire        stat_enable,
    input  wire        stat_upd,
    input  wire [7:0]  st_r0,
    input  wire [7:0]  st_g0,
    input  wire [7:0]  st_b0,
    input  wire [7:0]  st_r1,
    input  wire [7:0]  st_g1,
    input  wire [7:0]  st_b1,
    output reg         out_vs,
    output reg         out_hs,
    output reg         out_de,
    output reg  [23:0] out_rgb
);

    localparam [5:0] ID_BLANK = 6'd0;
    localparam [5:0] ID_MU    = 6'd1;    // target (1st char)
    localparam [5:0] ID_BIAO  = 6'd2;    // target (2nd char)
    localparam [5:0] ID_COLON = 6'd3;
    localparam [5:0] ID_RED   = 6'd4;    // 4..7 = red, green, blue, yellow
    localparam [5:0] ID_SE    = 6'd8;    // "colour" character
    localparam [5:0] ID_WEI   = 6'd9;    // not
    localparam [5:0] ID_FA    = 6'd10;   // found (1st char)
    localparam [5:0] ID_XIAN  = 6'd11;   // found (2nd char)
    localparam [5:0] ID_X     = 6'd12;
    localparam [5:0] ID_Y     = 6'd13;
    localparam [5:0] ID_YAN   = 6'd14;   // delay (1st char)
    localparam [5:0] ID_CHI   = 6'd15;   // delay (2nd char)
    localparam [5:0] ID_DIG0  = 6'd16;
    localparam [5:0] ID_M     = 6'd26;
    localparam [5:0] ID_S     = 6'd27;
    localparam [5:0] ID_R     = 6'd28;
    localparam [5:0] ID_G     = 6'd29;
    localparam [5:0] ID_B     = 6'd30;
    localparam [5:0] ID_P     = 6'd31;
    localparam [5:0] ID_XING  = 6'd32;   // shape (1st char)
    localparam [5:0] ID_ZHUANG= 6'd33;   // shape (2nd char)
    localparam [5:0] ID_JU    = 6'd34;   // rectangle
    localparam [5:0] ID_YUAN  = 6'd35;   // circle
    localparam [5:0] ID_SAN   = 6'd36;   // triangle (1st)
    localparam [5:0] ID_JIAO  = 6'd37;   // triangle (2nd)
    localparam [5:0] ID_ZHI   = 6'd38;   // confidence (1st)
    localparam [5:0] ID_XIN   = 6'd39;
    localparam [5:0] ID_DU    = 6'd40;
    localparam [5:0] ID_PCT   = 6'd41;
    localparam [5:0] ID_ZHEN  = 6'd42;   // frame
    localparam [5:0] ID_YUN   = 6'd43;   // motion (1st)
    localparam [5:0] ID_DONG  = 6'd44;   // motion (2nd)
    localparam [5:0] ID_CI    = 6'd45;   // times
    localparam [5:0] ID_QING  = 6'd46;   // sharpness (1st)
    localparam [5:0] ID_XI    = 6'd47;   // sharpness (2nd)

    function [15:0] glyph_row;
        input [5:0] gid;
        input [3:0] row;
        begin
            case({gid,row})
                10'd16: glyph_row = 16'h3FFC;  // U+76EE
                10'd17: glyph_row = 16'h3FFC;  // U+76EE
                10'd18: glyph_row = 16'h300C;  // U+76EE
                10'd19: glyph_row = 16'h300C;  // U+76EE
                10'd20: glyph_row = 16'h3FFC;  // U+76EE
                10'd21: glyph_row = 16'h3FFC;  // U+76EE
                10'd22: glyph_row = 16'h300C;  // U+76EE
                10'd23: glyph_row = 16'h300C;  // U+76EE
                10'd24: glyph_row = 16'h3FFC;  // U+76EE
                10'd25: glyph_row = 16'h3FFC;  // U+76EE
                10'd26: glyph_row = 16'h300C;  // U+76EE
                10'd27: glyph_row = 16'h300C;  // U+76EE
                10'd28: glyph_row = 16'h3FFC;  // U+76EE
                10'd29: glyph_row = 16'h3FFC;  // U+76EE
                10'd30: glyph_row = 16'h300C;  // U+76EE
                10'd31: glyph_row = 16'h0000;  // U+76EE
                10'd32: glyph_row = 16'h1800;  // U+6807
                10'd33: glyph_row = 16'h18FC;  // U+6807
                10'd34: glyph_row = 16'h19FE;  // U+6807
                10'd35: glyph_row = 16'h1800;  // U+6807
                10'd36: glyph_row = 16'hFE00;  // U+6807
                10'd37: glyph_row = 16'h79FE;  // U+6807
                10'd38: glyph_row = 16'h3DFE;  // U+6807
                10'd39: glyph_row = 16'h3C30;  // U+6807
                10'd40: glyph_row = 16'h7E30;  // U+6807
                10'd41: glyph_row = 16'h7DBC;  // U+6807
                10'd42: glyph_row = 16'hF9B6;  // U+6807
                10'd43: glyph_row = 16'hDB36;  // U+6807
                10'd44: glyph_row = 16'h1B36;  // U+6807
                10'd45: glyph_row = 16'h1B33;  // U+6807
                10'd46: glyph_row = 16'h18F0;  // U+6807
                10'd47: glyph_row = 16'h18E0;  // U+6807
                10'd48: glyph_row = 16'h0000;  // U+003A
                10'd49: glyph_row = 16'h0000;  // U+003A
                10'd50: glyph_row = 16'h0000;  // U+003A
                10'd51: glyph_row = 16'h0000;  // U+003A
                10'd52: glyph_row = 16'h0180;  // U+003A
                10'd53: glyph_row = 16'h0380;  // U+003A
                10'd54: glyph_row = 16'h0180;  // U+003A
                10'd55: glyph_row = 16'h0000;  // U+003A
                10'd56: glyph_row = 16'h0000;  // U+003A
                10'd57: glyph_row = 16'h0000;  // U+003A
                10'd58: glyph_row = 16'h0180;  // U+003A
                10'd59: glyph_row = 16'h0380;  // U+003A
                10'd60: glyph_row = 16'h0180;  // U+003A
                10'd61: glyph_row = 16'h0000;  // U+003A
                10'd62: glyph_row = 16'h0000;  // U+003A
                10'd63: glyph_row = 16'h0000;  // U+003A
                10'd64: glyph_row = 16'h1800;  // U+7EA2
                10'd65: glyph_row = 16'h19FE;  // U+7EA2
                10'd66: glyph_row = 16'h31FE;  // U+7EA2
