                10'd759: glyph_row = 16'h7BF6;  // U+6670
                10'd760: glyph_row = 16'h7BF6;  // U+6670
                10'd761: glyph_row = 16'h7FB6;  // U+6670
                10'd762: glyph_row = 16'h7FB6;  // U+6670
                10'd763: glyph_row = 16'h7DB6;  // U+6670
                10'd764: glyph_row = 16'h79A6;  // U+6670
                10'd765: glyph_row = 16'h61E6;  // U+6670
                10'd766: glyph_row = 16'h01E6;  // U+6670
                10'd767: glyph_row = 16'h01A4;  // U+6670
                default: glyph_row = 16'h0000;
            endcase
        end
    endfunction

    // ---- position counters on the incoming stream (y = 0 on the first active line) ----
    reg y_ovf;
    reg [10:0] x;
    reg [9:0]  y;
    reg        vs_d;
    reg        hs_d;
    reg        line_has_de;

    // ---- coordinates as decimal digits ----
    wire [15:0] bcd_x;
    wire [11:0] bcd_y;
    bin2bcd_seq #(.W(11), .D(4)) u_bcd_x (.clk(clk), .rst_n(rst_n), .start(upd), .bin(cx), .bcd(bcd_x));
    bin2bcd_seq #(.W(10), .D(3)) u_bcd_y (.clk(clk), .rst_n(rst_n), .start(upd), .bin(cy), .bcd(bcd_y));

    // ---- text ----
    wire [10:0] tx     = x - TXT_X;
    wire [9:0]  ty     = y - TXT_Y;
    wire        in_txt = enable && (tx < 11'd288) && (ty < 10'd16);
    wire [4:0]  ch     = tx[8:4];
    wire [3:0]  gx     = tx[3:0];
    wire [3:0]  gy     = ty[3:0];

    reg [5:0] chid;
    always @(*) begin
        chid = ID_BLANK;
        case(ch)
            5'd0:  chid = found ? ID_MU    : ID_WEI;
            5'd1:  chid = found ? ID_BIAO  : ID_FA;
            5'd2:  chid = found ? ID_COLON : ID_XIAN;
            5'd3:  chid = found ? (ID_RED + {3'b000, color_sel}) : ID_MU;
            5'd4:  chid = found ? ID_SE    : ID_BIAO;
            5'd6:  chid = found ? ID_X     : ID_BLANK;
            5'd7:  chid = found ? ID_COLON : ID_BLANK;
            5'd8:  chid = found ? (ID_DIG0 + {1'b0, bcd_x[15:12]}) : ID_BLANK;
            5'd9:  chid = found ? (ID_DIG0 + {1'b0, bcd_x[11:8]})  : ID_BLANK;
            5'd10: chid = found ? (ID_DIG0 + {1'b0, bcd_x[7:4]})   : ID_BLANK;
            5'd11: chid = found ? (ID_DIG0 + {1'b0, bcd_x[3:0]})   : ID_BLANK;
            5'd13: chid = found ? ID_Y     : ID_BLANK;
            5'd14: chid = found ? ID_COLON : ID_BLANK;
            5'd15: chid = found ? (ID_DIG0 + {1'b0, bcd_y[11:8]})  : ID_BLANK;
            5'd16: chid = found ? (ID_DIG0 + {1'b0, bcd_y[7:4]})   : ID_BLANK;
            5'd17: chid = found ? (ID_DIG0 + {1'b0, bcd_y[3:0]})   : ID_BLANK;
            default: chid = ID_BLANK;
        endcase
    end

    wire [15:0] txt_bits  = glyph_row(chid, gy);
    wire        txt_pixel = in_txt && txt_bits[15 - gx];

    // ---- line 2: shape + match score   [shape]:[rect|circle|triangle]  [confidence]:xx% ----
    wire [11:0] bcd_conf;
    bin2bcd_seq #(.W(7), .D(3)) u_bcd_conf (.clk(clk), .rst_n(rst_n), .start(shape_upd), .bin(conf), .bcd(bcd_conf));
    wire [9:0]  t2y     = y - (TXT_Y + 20);
    wire        in_t2   = enable && found && (tx < 11'd240) && (t2y < 10'd16);
    wire [3:0]  g2y     = t2y[3:0];
    reg  [5:0]  c2id;
    always @(*) begin
        c2id = ID_BLANK;
        case(ch)
            5'd0:  c2id = ID_XING;
            5'd1:  c2id = ID_ZHUANG;
            5'd2:  c2id = ID_COLON;
            5'd3:  c2id = (shape == 2'd0) ? ID_JU : ((shape == 2'd1) ? ID_YUAN : ID_SAN);
            5'd4:  c2id = (shape == 2'd2) ? ID_JIAO : ID_XING;
            5'd5:  c2id = (shape == 2'd2) ? ID_XING : ID_BLANK;
            5'd7:  c2id = ID_ZHI;
            5'd8:  c2id = ID_XIN;
            5'd9:  c2id = ID_DU;
            5'd10: c2id = ID_COLON;
            5'd11: c2id = (bcd_conf[11:8] == 4'd0) ? ID_BLANK : (ID_DIG0 + {2'b00, bcd_conf[11:8]});
            5'd12: c2id = (bcd_conf[11:4] == 8'd0) ? ID_BLANK : (ID_DIG0 + {2'b00, bcd_conf[7:4]});
            5'd13: c2id = ID_DIG0 + {2'b00, bcd_conf[3:0]};
            5'd14: c2id = ID_PCT;
            default: c2id = ID_BLANK;
        endcase
    end
    wire [15:0] t2_bits  = glyph_row(c2id, g2y);
    wire        t2_pixel = in_t2 && t2_bits[15 - gx];

    // ---- motion line (mode 7):  [motion]:nnnn  [times]:nnnn ----
    wire [15:0] bcd_mc;
    wire [15:0] bcd_me;
    bin2bcd_seq #(.W(13), .D(4)) u_bcd_mc (.clk(clk), .rst_n(rst_n), .start(mot_upd), .bin(mot_cnt), .bcd(bcd_mc));
    bin2bcd_seq #(.W(14), .D(4)) u_bcd_me (.clk(clk), .rst_n(rst_n), .start(mot_upd), .bin(mot_ev),  .bcd(bcd_me));
    wire        in_mt   = mot_enable && (tx < 11'd224) && (ty < 10'd16);
    reg  [5:0]  mid;
    always @(*) begin
        mid = ID_BLANK;
        case(ch)
            5'd0:  mid = ID_YUN;
            5'd1:  mid = ID_DONG;
            5'd2:  mid = ID_COLON;
            5'd3:  mid = ID_DIG0 + {2'b00, bcd_mc[15:12]};
            5'd4:  mid = ID_DIG0 + {2'b00, bcd_mc[11:8]};
            5'd5:  mid = ID_DIG0 + {2'b00, bcd_mc[7:4]};
            5'd6:  mid = ID_DIG0 + {2'b00, bcd_mc[3:0]};
            5'd8:  mid = ID_CI;
            5'd9:  mid = ID_COLON;
            5'd10: mid = ID_DIG0 + {2'b00, bcd_me[15:12]};
            5'd11: mid = ID_DIG0 + {2'b00, bcd_me[11:8]};
            5'd12: mid = ID_DIG0 + {2'b00, bcd_me[7:4]};
            5'd13: mid = ID_DIG0 + {2'b00, bcd_me[3:0]};
            default: mid = ID_BLANK;
        endcase
    end
    wire [15:0] mt_bits  = glyph_row(mid, gy);
    wire        mt_pixel = in_mt && mt_bits[15 - gx];

    // ---- latency text:  [delay]:xxx ms ----
    wire [11:0] bcd_lat;
    bin2bcd_seq #(.W(10), .D(3)) u_bcd_lat (.clk(clk), .rst_n(rst_n), .start(lat_upd), .bin(lat_ms), .bcd(bcd_lat));

    wire [10:0] lx      = x - LAT_X;
    wire        in_lat  = lat_enable && (lx < 11'd128) && (ty < 10'd16);
    wire [2:0]  lch     = lx[6:4];
    wire [3:0]  lgx     = lx[3:0];
    reg  [5:0]  lid;
    always @(*) begin
        case(lch)
            3'd0:    lid = ID_YAN;
            3'd1:    lid = ID_CHI;
            3'd2:    lid = ID_COLON;
            3'd3:    lid = ID_DIG0 + {1'b0, bcd_lat[11:8]};
            3'd4:    lid = ID_DIG0 + {1'b0, bcd_lat[7:4]};
            3'd5:    lid = ID_DIG0 + {1'b0, bcd_lat[3:0]};
            3'd6:    lid = ID_M;
            default: lid = ID_S;
        endcase
    end
    wire [15:0] lat_bits   = glyph_row(lid, gy);
    wire        lat_pixel  = in_lat && lat_bits[15 - lgx];

    // ---- latency visualisation: bar graph with camera-frame ticks + frame counter ----
    //   bar length = latency in ms (1 px per ms, 128 px full scale), yellow ticks at 1, 2, 3 camera frame periods,
    //   so the bar shows the latency in units of frames.  Below it: [frame]:nnnn camera frame counter.
    wire [10:0] bx       = x - LAT_X;
    wire [9:0]  by       = y - (TXT_Y + 20);
    wire        in_bar   = lat_enable && (bx < 11'd128) && (by < 10'd10);
    wire [9:0]  fp1      = {2'b00, fper};
    wire [9:0]  fp2      = {1'b0, fper, 1'b0};
    wire [9:0]  fp3      = fp2 + fp1;
    wire        on_tick  = in_bar && ((bx[9:0] == fp1) || (bx[9:0] == fp2) || (bx[9:0] == fp3));
    wire        on_fill  = in_bar && (by >= 10'd2) && (by < 10'd8) && (bx[9:0] < ((lat_ms > 10'd127) ? 10'd127 : lat_ms));
    wire        on_edge  = in_bar && ((by == 10'd0) || (by == 10'd9));
    wire [15:0] bcd_frm;
    bin2bcd_seq #(.W(14), .D(4)) u_bcd_frm (.clk(clk), .rst_n(rst_n), .start(lat_upd), .bin(frm_cnt), .bcd(bcd_frm));
    wire [9:0]  fy       = y - (TXT_Y + 40);
    wire        in_frm   = lat_enable && (lx < 11'd96) && (fy < 10'd16);
    wire [2:0]  fch      = lx[6:4];
    reg  [5:0]  fid;
    always @(*) begin
        fid = ID_BLANK;
        case(fch)
            3'd0: fid = ID_ZHEN;
            3'd1: fid = ID_COLON;
            3'd2: fid = ID_DIG0 + {2'b00, bcd_frm[15:12]};
            3'd3: fid = ID_DIG0 + {2'b00, bcd_frm[11:8]};
            3'd4: fid = ID_DIG0 + {2'b00, bcd_frm[7:4]};
            3'd5: fid = ID_DIG0 + {2'b00, bcd_frm[3:0]};
            default: fid = ID_BLANK;
        endcase
    end
    wire [15:0] frm_bits  = glyph_row(fid, fy[3:0]);
    wire        frm_pixel = in_frm && frm_bits[15 - lgx];

    // ---- focus (sharpness) read-out: [qing][xi][du]:nnnn and a bar relative to the recent peak ----

    wire [15:0] bcd_foc;

    bin2bcd_seq #(.W(14), .D(4)) u_bcd_foc (.clk(clk), .rst_n(rst_n), .start(foc_upd), .bin(foc_score), .bcd(bcd_foc));

    wire [9:0]  foc_ty    = y - (TXT_Y + 60);

    wire        in_foc    = lat_enable && (lx < 11'd128) && (foc_ty < 10'd16);

    reg  [5:0]  foc_id;

    always @(*) begin

        foc_id = ID_BLANK;

        case(lx[6:4])

            3'd0: foc_id = ID_QING;

            3'd1: foc_id = ID_XI;

            3'd2: foc_id = ID_DU;

            3'd3: foc_id = ID_COLON;

            3'd4: foc_id = ID_DIG0 + {2'b00, bcd_foc[15:12]};

            3'd5: foc_id = ID_DIG0 + {2'b00, bcd_foc[11:8]};

            3'd6: foc_id = ID_DIG0 + {2'b00, bcd_foc[7:4]};

            default: foc_id = ID_DIG0 + {2'b00, bcd_foc[3:0]};

        endcase

    end

    wire [15:0] foc_bits  = glyph_row(foc_id, foc_ty[3:0]);

    wire        foc_pixel = in_foc && foc_bits[15 - lgx];

    wire [9:0]  foc_by    = y - (TXT_Y + 80);

    wire        in_fbar   = lat_enable && (bx < 11'd128) && (foc_by < 10'd10);

    wire        on_ffill  = in_fbar && (foc_by >= 10'd2) && (foc_by < 10'd8) && (bx[6:0] < foc_bar);

    wire        on_fedge  = in_fbar && ((foc_by == 10'd0) || (foc_by == 10'd9));



    // ---- brightness read-out (two lines) ----
    wire [11:0] bcd_r0, bcd_g0, bcd_b0, bcd_r1, bcd_g1, bcd_b1;
    bin2bcd_seq #(.W(8), .D(3)) u_bcd_r0 (.clk(clk), .rst_n(rst_n), .start(stat_upd), .bin(st_r0), .bcd(bcd_r0));
    bin2bcd_seq #(.W(8), .D(3)) u_bcd_g0 (.clk(clk), .rst_n(rst_n), .start(stat_upd), .bin(st_g0), .bcd(bcd_g0));
    bin2bcd_seq #(.W(8), .D(3)) u_bcd_b0 (.clk(clk), .rst_n(rst_n), .start(stat_upd), .bin(st_b0), .bcd(bcd_b0));
    bin2bcd_seq #(.W(8), .D(3)) u_bcd_r1 (.clk(clk), .rst_n(rst_n), .start(stat_upd), .bin(st_r1), .bcd(bcd_r1));
    bin2bcd_seq #(.W(8), .D(3)) u_bcd_g1 (.clk(clk), .rst_n(rst_n), .start(stat_upd), .bin(st_g1), .bcd(bcd_g1));
    bin2bcd_seq #(.W(8), .D(3)) u_bcd_b1 (.clk(clk), .rst_n(rst_n), .start(stat_upd), .bin(st_b1), .bcd(bcd_b1));

    wire [10:0] sx      = x - STAT_X;
    wire [9:0]  sy0     = y - STAT_Y0;
    wire [9:0]  sy1     = y - STAT_Y1;
    wire        in_sx   = stat_enable && (sx < 11'd304);
    wire        in_s0   = in_sx && (sy0 < 10'd16);
    wire        in_s1   = in_sx && (sy1 < 10'd16);
    wire [4:0]  sch     = sx[8:4];
    wire [3:0]  sgx     = sx[3:0];
    wire [3:0]  sgy     = in_s0 ? sy0[3:0] : sy1[3:0];
    wire [11:0] sb_r    = in_s0 ? bcd_r0 : bcd_r1;
    wire [11:0] sb_g    = in_s0 ? bcd_g0 : bcd_g1;
    wire [11:0] sb_b    = in_s0 ? bcd_b0 : bcd_b1;
    reg  [5:0]  sid;
    always @(*) begin
        sid = ID_BLANK;
        case(sch)
            5'd0:  sid = in_s0 ? ID_P : ID_BLANK;
            5'd2:  sid = ID_R;
            5'd3:  sid = ID_COLON;
            5'd4:  sid = ID_DIG0 + {1'b0, sb_r[11:8]};
            5'd5:  sid = ID_DIG0 + {1'b0, sb_r[7:4]};
            5'd6:  sid = ID_DIG0 + {1'b0, sb_r[3:0]};
            5'd8:  sid = ID_G;
            5'd9:  sid = ID_COLON;
            5'd10: sid = ID_DIG0 + {1'b0, sb_g[11:8]};
            5'd11: sid = ID_DIG0 + {1'b0, sb_g[7:4]};
            5'd12: sid = ID_DIG0 + {1'b0, sb_g[3:0]};
            5'd14: sid = ID_B;
            5'd15: sid = ID_COLON;
            5'd16: sid = ID_DIG0 + {1'b0, sb_b[11:8]};
            5'd17: sid = ID_DIG0 + {1'b0, sb_b[7:4]};
            5'd18: sid = ID_DIG0 + {1'b0, sb_b[3:0]};
            default: sid = ID_BLANK;
        endcase
    end
    wire [15:0] st_bits  = glyph_row(sid, sgy);
    wire        st_pixel = (in_s0 || in_s1) && st_bits[15 - sgx];

    // ---- box (3 px border) and cross (3 px wide arms, +-10 px) ----
    wire in_outer = found && (x >= x0) && (x <= x1) && (y >= y0) && (y <= y1);
    wire in_inner = (x >= x0 + 3) && (x + 3 <= x1) && (y >= y0 + 3) && (y + 3 <= y1);
    wire box_pixel = in_outer && !in_inner;

    wire cross_h = found && (y + 1 >= cy) && (y <= cy + 1) && (x + 10 >= cx) && (x <= cx + 10);
    wire cross_v = found && (x + 1 >= cx) && (x <= cx + 1) && (y + 10 >= cy) && (y <= cy + 10);

    wire [23:0] mark_color = (color_sel == 2'd3) ? 24'h00FFFF : 24'hFFFF00;

    always @(posedge clk or negedge rst_n) begin
        if(!rst_n) begin
            x <= 11'd0;
            y <= 10'd0;
            y_ovf <= 1'b0;
            vs_d <= 1'b0;
            hs_d <= 1'b0;
            line_has_de <= 1'b0;
            out_vs <= 1'b0;
            out_hs <= 1'b0;
            out_de <= 1'b0;
            out_rgb <= 24'd0;
        end
        else begin
            vs_d <= in_vs;
            hs_d <= in_hs;

            if(in_vs && !vs_d) begin
                x <= 11'd0;
                y <= 10'd0;
                y_ovf <= 1'b0;
                line_has_de <= 1'b0;
            end
            else if(!in_hs && hs_d) begin
                x <= 11'd0;
                if(line_has_de) begin
                    y <= y + 10'd1;
                    if(y == 10'h3FF) y_ovf <= 1'b1;
                end
                line_has_de <= 1'b0;
            end
            else if(in_de) begin
                x <= x + 11'd1;
                line_has_de <= 1'b1;
            end

            out_vs <= in_vs;
            out_hs <= in_hs;
            out_de <= in_de;

            if(y_ovf)
                out_rgb <= in_rgb;   // 1080p: y wrapped (>= 1024), no overlay
            else if(in_de && on_tick)
                out_rgb <= 24'hFFFF00;
            else if(in_de && on_fill)
                out_rgb <= 24'h00D000;
            else if(in_de && on_ffill)
                out_rgb <= 24'h00C8FF;
            else if(in_de && (on_edge || on_fedge))
                out_rgb <= 24'hFFFFFF;
            else if(in_de && (lat_pixel || frm_pixel || foc_pixel || st_pixel || (enable && txt_pixel) || t2_pixel || mt_pixel))
                out_rgb <= 24'hFFFFFF;
            else if(enable && in_de && (box_pixel || cross_h || cross_v))
                out_rgb <= mark_color;
            else
                out_rgb <= in_rgb;
        end
    end

endmodule


// ----------------------------------------------------------------------------
// Frame brightness statistics (pixel clock domain).
//   Averages R, G, B (8 bit) over the pixels where win is high, once per frame, for two taps:
//   tap 0 = video before the digital gain, tap 1 = video after the digital gain (displayed).
//   The averages are computed at the rising edge of vs (after the active area) by one
//   sequential restoring divider that is reused for the six sums.  upd pulses when done.
// ----------------------------------------------------------------------------
module rgb_stats (
    input  wire        clk,
    input  wire        rst_n,
    input  wire        vs,
    input  wire        win,
    input  wire [23:0] pre,
    input  wire [23:0] post,
    output reg  [7:0]  a_r0,
    output reg  [7:0]  a_g0,
    output reg  [7:0]  a_b0,
    output reg  [7:0]  a_r1,
    output reg  [7:0]  a_g1,
    output reg  [7:0]  a_b1,
    output reg         upd
);
    reg [27:0] s0, s1, s2, s3, s4, s5;
    reg [27:0] l0, l1, l2, l3, l4, l5;
    reg [19:0] cnt;
    reg [19:0] den;
    reg        vs_d;
    reg        run;
    reg [1:0]  sub;       // 1080p: accumulate every 4th window pixel so cnt and the 28-bit sums cannot overflow
    reg [2:0]  idx;
    reg [4:0]  bcnt;
    reg [20:0] rem;
    reg [27:0] quo;

    wire        vs_rise = vs && !vs_d;
    wire [20:0] rem_sh  = {rem[19:0], quo[27]};
    wire        ge      = (rem_sh >= {1'b0, den});
    wire [20:0] rem_nx  = ge ? (rem_sh - {1'b0, den}) : rem_sh;
    wire [27:0] quo_nx  = {quo[26:0], ge};
    wire [7:0]  res8    = (den == 20'd0) ? 8'd0 : ((|quo_nx[27:8]) ? 8'hFF : quo_nx[7:0]);

    function [27:0] pick;
        input [2:0] i;
        input [27:0] a0, a1, a2, a3, a4, a5;
        begin
            case(i)
                3'd0: pick = a0;
                3'd1: pick = a1;
                3'd2: pick = a2;
                3'd3: pick = a3;
                3'd4: pick = a4;
                default: pick = a5;
            endcase
        end
    endfunction

    always @(posedge clk or negedge rst_n) begin
        if(!rst_n) begin
            s0 <= 28'd0; s1 <= 28'd0; s2 <= 28'd0; s3 <= 28'd0; s4 <= 28'd0; s5 <= 28'd0;
            l0 <= 28'd0; l1 <= 28'd0; l2 <= 28'd0; l3 <= 28'd0; l4 <= 28'd0; l5 <= 28'd0;
            cnt <= 20'd0;
            den <= 20'd1;
            vs_d <= 1'b0;
            run <= 1'b0;
            idx <= 3'd0;
            sub <= 2'd0;
            bcnt <= 5'd0;
            rem <= 21'd0;
            quo <= 28'd0;
            a_r0 <= 8'd0; a_g0 <= 8'd0; a_b0 <= 8'd0;
            a_r1 <= 8'd0; a_g1 <= 8'd0; a_b1 <= 8'd0;
            upd <= 1'b0;
        end
        else begin
            vs_d <= vs;
            upd  <= 1'b0;

            if(vs_rise) begin
                l0 <= s0; l1 <= s1; l2 <= s2; l3 <= s3; l4 <= s4; l5 <= s5;
                den <= cnt;
                s0 <= 28'd0; s1 <= 28'd0; s2 <= 28'd0; s3 <= 28'd0; s4 <= 28'd0; s5 <= 28'd0;
                cnt <= 20'd0;
                run <= 1'b1;
                idx <= 3'd0;
                bcnt <= 5'd0;
                rem <= 21'd0;
                quo <= s0;
            end
            else begin
                if(win) sub <= sub + 2'd1;
                if(win && sub == 2'd0) begin
                    s0  <= s0 + {20'd0, pre[23:16]};
                    s1  <= s1 + {20'd0, pre[15:8]};
                    s2  <= s2 + {20'd0, pre[7:0]};
                    s3  <= s3 + {20'd0, post[23:16]};
                    s4  <= s4 + {20'd0, post[15:8]};
                    s5  <= s5 + {20'd0, post[7:0]};
                    cnt <= cnt + 20'd1;
                end

                if(run) begin
                    rem <= rem_nx;
                    quo <= quo_nx;
                    if(bcnt == 5'd27) begin
                        case(idx)
                            3'd0: a_r0 <= res8;
                            3'd1: a_g0 <= res8;
                            3'd2: a_b0 <= res8;
                            3'd3: a_r1 <= res8;
                            3'd4: a_g1 <= res8;
                            default: a_b1 <= res8;
                        endcase
                        bcnt <= 5'd0;
                        rem <= 21'd0;
                        if(idx == 3'd5) begin
                            run <= 1'b0;
                            upd <= 1'b1;
                        end
                        else begin
                            idx <= idx + 3'd1;
                            quo <= pick(idx + 3'd1, l0, l1, l2, l3, l4, l5);
                        end
                    end
                    else
                        bcnt <= bcnt + 5'd1;
                end
            end
        end
    end
endmodule


// ----------------------------------------------------------------------------
// Auto digital gain (pixel clock domain).
//   Closed loop on the average green level of the DISPLAYED image (after the gain):
//   once per frame (upd), if the average is below LOW the gain is raised by about 12 %,
//   if it is above HIGH it is lowered by about 12 %.  gain is in 1/16 steps (16 = 1x).
// ----------------------------------------------------------------------------
module auto_gain #(
    parameter [7:0] G_MIN  = 8'd16,
    parameter [7:0] G_MAX  = 8'd192,
    parameter [7:0] G_INIT = 8'd96,
    parameter [7:0] LOW    = 8'd100,
    parameter [7:0] HIGH   = 8'd125
)(
    input  wire       clk,
    input  wire       rst_n,
    input  wire       upd,
    input  wire [7:0] avg,
    output reg  [7:0] gain
);
    wire [7:0] step = (gain[7:3] == 5'd0) ? 8'd1 : {3'd0, gain[7:3]};
    wire [8:0] up   = {1'b0, gain} + {1'b0, step};
    wire [8:0] dn   = {1'b0, gain} - {1'b0, step};
    always @(posedge clk or negedge rst_n) begin
        if(!rst_n)
            gain <= G_INIT;
        else if(upd) begin
            if(avg < LOW)
                gain <= (up > {1'b0, G_MAX}) ? G_MAX : up[7:0];
            else if(avg > HIGH)
                gain <= (dn < {1'b0, G_MIN}) ? G_MIN : dn[7:0];
        end
    end
endmodule


// ----------------------------------------------------------------------------
// Latency meter (pixel clock domain).
//   Measures the time from the start of the camera frame that is being displayed to the
//   moment the first image line of that frame starts to be shown, in milliseconds.
//   - cam_toggle toggles on every camera frame start (generated in the camera clock domain)
//   - the last four camera frame start times are kept; HIST selects the displayed one:
//     HIST = 4 - READ_OFFSET of video_in (1 = most recent complete frame, 2 = the one before)
//   - vs is the display vsync (active high); the sample is taken when it ends, which is when
//     video_out latches its read pointer; EXTRA_MS (2) covers the time until the first image line
//   - 16 samples are averaged; lat_upd pulses when lat_ms is updated.
//   Not included: sensor exposure/readout and the ISP pipeline before the frame-start marker.
// ----------------------------------------------------------------------------
module latency_meter #(
    parameter integer HIST       = 1,
    parameter integer PIX_PER_MS = 74250,
    parameter integer EXTRA_MS   = 2
)(
    input  wire       clk,
    input  wire       rst_n,
    input  wire       cam_toggle,
    input  wire       vs,
    output reg  [9:0] lat_ms,
    output reg        lat_upd,
    output reg  [13:0] frm_cnt,      // camera frame counter (0..9999)
    output reg  [7:0]  fper          // measured camera frame period in ms (33 at 30 fps)
);
    reg [16:0] tick;
    reg [15:0] ms;
    reg        t1;
    reg        t2;
    reg        t3;
    reg [15:0] ts0;
    reg [15:0] ts1;
    reg [15:0] ts2;
    reg [15:0] ts3;
    reg [2:0]  nstart;
    reg        vs_d;
    reg [15:0] acc;
    reg [3:0]  n;

    wire        cam_pulse  = t2 ^ t3;
    wire        disp_start = vs_d && !vs;
    wire [15:0] ts_sel     = (HIST == 1) ? ts1 : ((HIST == 2) ? ts2 : ((HIST == 3) ? ts3 : ts0));
    wire [15:0] diff       = ms - ts_sel + EXTRA_MS;
    wire [15:0] d_sat      = (diff > 16'd999 || nstart < 3'd4) ? 16'd999 : diff;
    wire [15:0] acc_new    = acc + d_sat;

    always @(posedge clk or negedge rst_n) begin
        if(!rst_n) begin
            tick   <= 17'd0;
            ms     <= 16'd0;
            t1     <= 1'b0;
            t2     <= 1'b0;
            t3     <= 1'b0;
            ts0    <= 16'd0;
            ts1    <= 16'd0;
            ts2    <= 16'd0;
            ts3    <= 16'd0;
            nstart <= 3'd0;
            vs_d   <= 1'b0;
            acc    <= 16'd0;
            n      <= 4'd0;
            lat_ms <= 10'd0;
            lat_upd <= 1'b0;
            frm_cnt <= 14'd0;
            fper    <= 8'd33;
        end
        else begin
            lat_upd <= 1'b0;

            if(tick == PIX_PER_MS - 1) begin
                tick <= 17'd0;
                ms   <= ms + 16'd1;
            end
            else
                tick <= tick + 17'd1;

            t1 <= cam_toggle;
            t2 <= t1;
            t3 <= t2;
            if(cam_pulse) begin
                frm_cnt <= (frm_cnt == 14'd9999) ? 14'd0 : (frm_cnt + 14'd1);
                if(nstart != 3'd0)
                    fper <= ((ms - ts0) > 16'd255) ? 8'd255 : (ms - ts0);
                ts0 <= ms;
                ts1 <= ts0;
                ts2 <= ts1;
                ts3 <= ts2;
                if(nstart != 3'd7)
                    nstart <= nstart + 3'd1;
            end

            vs_d <= vs;
            if(disp_start) begin
                if(n == 4'd15) begin
                    lat_ms  <= acc_new[13:4];     // average of 16 samples
                    lat_upd <= 1'b1;
                    acc     <= 16'd0;
                    n       <= 4'd0;
                end
                else begin
                    acc <= acc_new;
                    n   <= n + 4'd1;
                end
            end
        end
    end
endmodule

// ----------------------------------------------------------------------------
// Motion detection by frame differencing (hardware, block based).
//   The camera window (896 x 528 pixels from (160,90)) is divided into 8x8 pixel blocks (112 x 66).
//   For every block the mean gray value ((R+2G+B)/4) is computed on the fly and compared with the mean of
//   the same block in the previous frame (kept in block RAM, 1 byte per block).  |diff| >= TH marks the
//   block as moving.  The result is kept in a 1-bit map that the overlay reads one frame later.
//   Per frame (published at vsync):  number of moving blocks, bounding box of the moving blocks, and an
//   event counter (rising edge of "motion present", i.e. at least MIN_BLK moving blocks).
//   If more than GLOBAL_MAX blocks move the frame is treated as a global change (light / auto gain
//   step / camera shake) and ignored.
//   m_*  : clean video stream that is analysed (measurement)
//   o_*  : stream that receives the overlay (moving blocks tinted red, cyan bounding box)
//   Overlay is drawn only when enable = 1; the analysis always runs.
// ----------------------------------------------------------------------------
module motion_detect #(
    parameter integer TH         = 12,
    parameter integer MIN_BLK    = 4,
    parameter integer GLOBAL_MAX = 4400
)(
    input  wire        clk,
    input  wire        rst_n,
    input  wire        m_vs,
    input  wire        m_hs,
    input  wire        m_de,
    input  wire [23:0] m_rgb,
    input  wire        o_vs,
    input  wire        o_hs,
    input  wire        o_de,
    input  wire [23:0] o_rgb,
    input  wire        enable,
    output reg         out_vs,
    output reg         out_hs,
    output reg         out_de,
    output reg  [23:0] out_rgb,
    output reg  [12:0] mot_cnt,
    output reg  [13:0] mot_ev,
    output reg         mot_upd
);

    // ---------------- measurement: position counters ----------------
    reg [10:0] x;
    reg [9:0]  y;
    reg        vs_d;
    reg        hs_d;
    reg        line_has_de;

    wire [10:0] xr    = x - 11'd512;
    wire [9:0]  yr    = y - 10'd276;
    wire        in_reg = m_de && (xr < 11'd896) && (yr < 10'd528);
    wire [9:0]  gsum  = {2'b00, m_rgb[23:16]} + {1'b0, m_rgb[15:8], 1'b0} + {2'b00, m_rgb[7:0]};
    wire [7:0]  gray  = gsum[9:2];

    // stage 0: horizontal sum of 8 pixels
    reg [10:0] hsum;
    reg        ev0;
    reg [10:0] e_sum;
    reg [6:0]  e_bx;
    reg [6:0]  e_by;
    reg        e_first;
    reg        e_last;

    // stage 1..3 pipeline
    reg [13:0] acc_m [0:127];
    reg [13:0] acc_q;
    reg        s1_v, s1_first, s1_last;
    reg [10:0] s1_sum;
    reg [6:0]  s1_bx, s1_by;
    wire [13:0] newacc = (s1_first ? 14'd0 : acc_q) + {3'b000, s1_sum};
    wire [12:0] s1_addr = {s1_by, 6'b000000} + {1'b0, s1_by, 5'b00000} + {2'b00, s1_by, 4'b0000} + {6'b000000, s1_bx};

    reg        s2_v;
    reg [13:0] s2_acc;
    reg [6:0]  s2_bx, s2_by;
    reg [12:0] s2_addr;

    reg [7:0]  prev_m [0:8191];
    reg [7:0]  prev_q;
    reg        s3_v;
    reg [13:0] s3_acc;
    reg [6:0]  s3_bx, s3_by;
    reg [12:0] s3_addr;

    reg        map_m [0:8191];
    reg [1:0]  warm;

    wire [7:0] avg  = s3_acc[13:6];
    wire [7:0] diff = (avg >= prev_q) ? (avg - prev_q) : (prev_q - avg);
    wire       mot  = (diff >= TH) && (warm == 2'd3);

    reg [12:0] cnt_blk;
    reg [6:0]  bminx, bmaxx, bminy, bmaxy;

    // published results
    reg        pub_active;
    reg        pub_glob;
    reg [6:0]  pminx, pmaxx, pminy, pmaxy;

    wire        active_new = (cnt_blk >= MIN_BLK) && (cnt_blk <= GLOBAL_MAX);

    always @(posedge clk or negedge rst_n) begin
        if(!rst_n) begin
            x <= 11'd0; y <= 10'd0; vs_d <= 1'b0; hs_d <= 1'b0; line_has_de <= 1'b0;
            hsum <= 11'd0; ev0 <= 1'b0; e_sum <= 11'd0; e_bx <= 7'd0; e_by <= 7'd0; e_first <= 1'b0; e_last <= 1'b0;
            s1_v <= 1'b0; s1_first <= 1'b0; s1_last <= 1'b0; s1_sum <= 11'd0; s1_bx <= 7'd0; s1_by <= 7'd0;
            s2_v <= 1'b0; s2_acc <= 14'd0; s2_bx <= 7'd0; s2_by <= 7'd0; s2_addr <= 13'd0;
            s3_v <= 1'b0; s3_acc <= 14'd0; s3_bx <= 7'd0; s3_by <= 7'd0; s3_addr <= 13'd0;
            warm <= 2'd0;
            cnt_blk <= 13'd0; bminx <= 7'h7F; bmaxx <= 7'd0; bminy <= 7'h7F; bmaxy <= 7'd0;
            pub_active <= 1'b0; pub_glob <= 1'b0; pminx <= 7'd0; pmaxx <= 7'd0; pminy <= 7'd0; pmaxy <= 7'd0;
            mot_cnt <= 13'd0; mot_ev <= 14'd0; mot_upd <= 1'b0;
        end
        else begin
            vs_d <= m_vs;
            hs_d <= m_hs;
            mot_upd <= 1'b0;

            if(m_vs && !vs_d) begin
                x <= 11'd0; y <= 10'd0; line_has_de <= 1'b0;
            end
            else if(!m_hs && hs_d) begin
                x <= 11'd0;
                if(line_has_de) y <= y + 10'd1;
                line_has_de <= 1'b0;
            end
            else if(m_de) begin
                x <= x + 11'd1;
                line_has_de <= 1'b1;
            end

            // ---- stage 0 ----
            ev0 <= 1'b0;
            if(in_reg) begin
                if(xr[2:0] == 3'd0) hsum <= {3'b000, gray};
                else                hsum <= hsum + {3'b000, gray};
                if(xr[2:0] == 3'd7) begin
                    ev0     <= 1'b1;
                    e_sum   <= hsum + {3'b000, gray};
                    e_bx    <= xr[9:3];
                    e_by    <= yr[9:3];
                    e_first <= (yr[2:0] == 3'd0);
                    e_last  <= (yr[2:0] == 3'd7);
                end
            end

            // ---- stage 1 (acc_q is read in the memory block below) ----
            s1_v <= ev0; s1_sum <= e_sum; s1_bx <= e_bx; s1_by <= e_by; s1_first <= e_first; s1_last <= e_last;
            // ---- stage 2 ----
            s2_v <= s1_v && s1_last; s2_acc <= newacc; s2_bx <= s1_bx; s2_by <= s1_by; s2_addr <= s1_addr;
            // ---- stage 3 (prev_q read in the memory block below) ----
            s3_v <= s2_v; s3_acc <= s2_acc; s3_bx <= s2_bx; s3_by <= s2_by; s3_addr <= s2_addr;

            // ---- block result ----
            if(s3_v && mot) begin
                cnt_blk <= cnt_blk + 13'd1;
                if(s3_bx < bminx) bminx <= s3_bx;
                if(s3_bx > bmaxx) bmaxx <= s3_bx;
                if(s3_by < bminy) bminy <= s3_by;
                if(s3_by > bmaxy) bmaxy <= s3_by;
            end

            // ---- frame end: publish ----
            if(m_vs && !vs_d) begin
                if(warm != 2'd3) warm <= warm + 2'd1;
                pub_glob   <= (cnt_blk > GLOBAL_MAX);
                pub_active <= active_new;
                mot_cnt    <= (cnt_blk > GLOBAL_MAX) ? 13'd0 : cnt_blk;
                if(active_new) begin
                    pminx <= bminx; pmaxx <= bmaxx; pminy <= bminy; pmaxy <= bmaxy;
                    if(!pub_active) mot_ev <= (mot_ev == 14'd9999) ? 14'd0 : (mot_ev + 14'd1);
                end
                mot_upd <= 1'b1;
                cnt_blk <= 13'd0;
                bminx <= 7'h7F; bmaxx <= 7'd0; bminy <= 7'h7F; bmaxy <= 7'd0;
            end
        end
    end

    // block RAM style memories (synchronous read)
    always @(posedge clk) begin
        acc_q <= acc_m[e_bx];
        if(s1_v) acc_m[s1_bx] <= newacc;
    end
    always @(posedge clk) begin
        prev_q <= prev_m[s2_addr];
        if(s3_v) prev_m[s3_addr] <= avg;
    end
    always @(posedge clk) begin
        if(s3_v) map_m[s3_addr] <= mot;
    end

    // ---------------- overlay stream ----------------
    reg [10:0] ox;
    reg [9:0]  oy;
    reg        ovs_d;
    reg        ohs_d;
    reg        oline_has_de;

    wire [10:0] oxr    = ox - 11'd512;
    wire [9:0]  oyr    = oy - 10'd276;
    wire        o_in   = o_de && (oxr < 11'd896) && (oyr < 10'd528);
    wire [6:0]  obx    = oxr[9:3];
    wire [6:0]  oby    = oyr[9:3];
    wire [12:0] o_addr = {oby, 6'b000000} + {1'b0, oby, 5'b00000} + {2'b00, oby, 4'b0000} + {6'b000000, obx};

    wire [10:0] bxl = 11'd512 + {pminx, 3'b000};
    wire [10:0] bxr = 11'd512 + {pmaxx, 3'b000} + 11'd7;
    wire [10:0] byt = 11'd90  + {pminy, 3'b000};
    wire [10:0] byb = 11'd90  + {pmaxy, 3'b000} + 11'd7;
    wire [10:0] oy11 = {1'b0, oy};
    wire        b_out = pub_active && !pub_glob && (ox >= bxl) && (ox <= bxr) && (oy11 >= byt) && (oy11 <= byb);
    wire        b_in  = (ox >= bxl + 11'd2) && (ox + 11'd2 <= bxr) && (oy11 >= byt + 11'd2) && (oy11 + 11'd2 <= byb);
    wire        box_px = o_de && b_out && !b_in;

    reg        p1_vs, p1_hs, p1_de, p1_in, p1_box;
    reg [23:0] p1_rgb;
    reg [12:0] p1_addr;
    reg        p2_vs, p2_hs, p2_de, p2_in, p2_box;
    reg [23:0] p2_rgb;
    reg        map_q;

    always @(posedge clk) begin
        map_q <= map_m[p1_addr];
    end

    wire tint = enable && p2_in && map_q && pub_active && !pub_glob;
    wire [7:0]  tint_r   = {1'b0, p2_rgb[23:17]} + 8'd96;
    wire [23:0] tint_rgb = {tint_r, 1'b0, p2_rgb[15:9], 1'b0, p2_rgb[7:1]};

    always @(posedge clk or negedge rst_n) begin
        if(!rst_n) begin
            ox <= 11'd0; oy <= 10'd0; ovs_d <= 1'b0; ohs_d <= 1'b0; oline_has_de <= 1'b0;
            p1_vs <= 1'b0; p1_hs <= 1'b0; p1_de <= 1'b0; p1_in <= 1'b0; p1_box <= 1'b0; p1_rgb <= 24'd0; p1_addr <= 13'd0;
            p2_vs <= 1'b0; p2_hs <= 1'b0; p2_de <= 1'b0; p2_in <= 1'b0; p2_box <= 1'b0; p2_rgb <= 24'd0;
            out_vs <= 1'b0; out_hs <= 1'b0; out_de <= 1'b0; out_rgb <= 24'd0;
        end
        else begin
            ovs_d <= o_vs;
            ohs_d <= o_hs;
            if(o_vs && !ovs_d) begin
                ox <= 11'd0; oy <= 10'd0; oline_has_de <= 1'b0;
            end
            else if(!o_hs && ohs_d) begin
                ox <= 11'd0;
                if(oline_has_de) oy <= oy + 10'd1;
                oline_has_de <= 1'b0;
            end
            else if(o_de) begin
                ox <= ox + 11'd1;
                oline_has_de <= 1'b1;
            end

            p1_vs <= o_vs; p1_hs <= o_hs; p1_de <= o_de; p1_rgb <= o_rgb;
            p1_in <= o_in; p1_box <= box_px; p1_addr <= o_addr;

            p2_vs <= p1_vs; p2_hs <= p1_hs; p2_de <= p1_de; p2_rgb <= p1_rgb;
            p2_in <= p1_in; p2_box <= p1_box;

            out_vs <= p2_vs; out_hs <= p2_hs; out_de <= p2_de;
            if(enable && p2_de && p2_box)
                out_rgb <= 24'h00FFFF;
            else if(p2_de && tint)
                out_rgb <= tint_rgb;
            else
                out_rgb <= p2_rgb;
        end
    end
endmodule

// ----------------------------------------------------------------------------
// Histogram equalisation (global contrast enhancement), 256 gray levels.
//   - The gray histogram (R+2G+B)/4 of the camera window is collected on a sub-sampled grid
//     (every 4th pixel of every 2nd line, about 65k samples per frame) in block RAM.
//   - In the blanking time after the frame (vsync) a small state machine walks over the 256 bins,
//     accumulates the CDF and converts it to a mapping table  q = 255 * cdf / total  without a divider
//     (incremental division, at most about 1100 clocks), clears the histogram on the way, and writes
//     lut[i] = (q + i) / 2  (50 % blend with the identity curve: limits noise amplification).
//   - The table is applied to R, G and B of the next frame (one table copy per channel).
//   en = 0 : pass-through.  Latency is 2 pixel clocks in both cases.
// ----------------------------------------------------------------------------
module hist_eq (
    input  wire        clk,
    input  wire        rst_n,
    input  wire        en,
    input  wire        in_vs,
    input  wire        in_hs,
    input  wire        in_de,
    input  wire        in_win,
    input  wire [23:0] in_rgb,
    output reg         out_vs,
    output reg         out_hs,
    output reg         out_de,
    output reg         out_win,
    output reg  [23:0] out_rgb
);
    // ---------- position / sampling ----------
    reg [10:0] x;
    reg [9:0]  y;
    reg        vs_d, hs_d, line_has_de;

    wire [9:0] gsum   = {2'b00, in_rgb[23:16]} + {1'b0, in_rgb[15:8], 1'b0} + {2'b00, in_rgb[7:0]};
    wire [7:0] gray   = gsum[9:2];
    wire       sample = in_de && in_win && (x[1:0] == 2'b00) && (y[0] == 1'b0);

    reg        s1_v, s2_v;
    reg [7:0]  g1, g2;
    reg [18:0] total;
    reg [18:0] total_l;

    // ---------- histogram RAM ----------
    reg [19:0] hist [0:255];
    reg [19:0] hist_q;
    reg [2:0]  st;
    reg [7:0]  i;
    wire       busy  = (st != 3'd0);
    wire [7:0] raddr = busy ? i : g1;
    wire       hwe   = busy ? (st == 3'd2 || st == 3'd6) : s2_v;   // st 6: power-up sweep also clears the bin
    wire [7:0] waddr = busy ? i : g2;
    wire [19:0] hwd  = busy ? 20'd0 : (hist_q + 20'd1);

    always @(posedge clk) begin
        hist_q <= hist[raddr];
        if(hwe) hist[waddr] <= hwd;
    end

    // ---------- LUT RAMs (one copy per colour channel) ----------
    reg [7:0] lut_r [0:255];
    reg [7:0] lut_g [0:255];
    reg [7:0] lut_b [0:255];
    reg [7:0] q_r, q_g, q_b;
    reg [7:0] lw;
    reg       lwe;
    always @(posedge clk) begin
        q_r <= lut_r[in_rgb[23:16]];
        q_g <= lut_g[in_rgb[15:8]];
        q_b <= lut_b[in_rgb[7:0]];
        if(lwe) begin
            lut_r[i] <= lw;
            lut_g[i] <= lw;
            lut_b[i] <= lw;
        end
    end

    // ---------- table builder ----------
    reg [27:0] num;
    reg [8:0]  qv;
    wire [27:0] hx255 = {hist_q[19:0], 8'd0} - {8'd0, hist_q};
    wire [8:0]  mix   = {1'b0, qv[7:0]} + {1'b0, i};

    always @(posedge clk or negedge rst_n) begin
        if(!rst_n) begin
            x <= 11'd0; y <= 10'd0; vs_d <= 1'b0; hs_d <= 1'b0; line_has_de <= 1'b0;
            s1_v <= 1'b0; s2_v <= 1'b0; g1 <= 8'd0; g2 <= 8'd0; total <= 19'd0; total_l <= 19'd0;
            st <= 3'd6; i <= 8'd0; num <= 28'd0; qv <= 9'd0; lw <= 8'd0; lwe <= 1'b0;   // start with the power-up sweep (RAM contents are not guaranteed to be 0)
        end
        else begin
            vs_d <= in_vs;
            hs_d <= in_hs;
            lwe  <= 1'b0;

            if(in_vs && !vs_d) begin
                x <= 11'd0; y <= 10'd0; line_has_de <= 1'b0;
            end
            else if(!in_hs && hs_d) begin
                x <= 11'd0;
                if(line_has_de) y <= y + 10'd1;
                line_has_de <= 1'b0;
            end
            else if(in_de) begin
                x <= x + 11'd1;
                line_has_de <= 1'b1;
            end

            // sampling pipeline
            s1_v <= sample && !busy;
            g1   <= gray;
            s2_v <= s1_v;
            g2   <= g1;
            if(sample && !busy) total <= total + 19'd1;

            // frame end: start the table builder
            if(in_vs && !vs_d) begin
                total_l <= total;
                total   <= 19'd0;
                if(total != 19'd0 && !busy) begin
                    st  <= 3'd1;
                    i   <= 8'd0;
                    num <= 28'd0;
                    qv  <= 9'd0;
                end
            end
            else begin
                case(st)
                    3'd6: begin                                    // power-up sweep: hist[i] <= 0 (hwe), lut[i] <= i (identity)
                        lw  <= i;
                        lwe <= 1'b1;
                        st  <= 3'd7;
                    end
                    3'd7: begin
                        if(i == 8'd255) st <= 3'd0;
                        else begin
                            i  <= i + 8'd1;
                            st <= 3'd6;
                        end
                    end
                    3'd1: st <= 3'd2;                              // address i applied, hist_q valid next clock
                    3'd2: begin                                    // hist_q = hist[i]; hist[i] is cleared now
                        num <= num + hx255;
                        st  <= 3'd3;
                    end
                    3'd3: begin
                        if(num >= {9'd0, total_l}) begin
                            num <= num - {11'd0, total_l};
                            if(qv != 9'd255) qv <= qv + 9'd1;
                        end
                        else
                            st <= 3'd4;
                    end
                    3'd4: begin
                        lw  <= mix[8:1];
                        lwe <= 1'b1;
                        st  <= 3'd5;
                    end
                    default: begin                                 // st 5: lut written, next bin
                        if(i == 8'd255) st <= 3'd0;
                        else begin
                            i  <= i + 8'd1;
                            st <= 3'd1;
                        end
                    end
                endcase
            end
        end
    end

    // ---------- output ----------
    reg        p_vs, p_hs, p_de, p_win;
    reg [23:0] p_rgb;
    always @(posedge clk or negedge rst_n) begin
        if(!rst_n) begin
            p_vs <= 1'b0; p_hs <= 1'b0; p_de <= 1'b0; p_win <= 1'b0; p_rgb <= 24'd0;
            out_vs <= 1'b0; out_hs <= 1'b0; out_de <= 1'b0; out_win <= 1'b0; out_rgb <= 24'd0;
        end
        else begin
            p_vs <= in_vs; p_hs <= in_hs; p_de <= in_de; p_win <= in_win; p_rgb <= in_rgb;
            out_vs <= p_vs; out_hs <= p_hs; out_de <= p_de; out_win <= p_win;
            out_rgb <= (en && p_win) ? {q_r, q_g, q_b} : p_rgb;
        end
    end
endmodule


// ---------------------------------------------------------------------------
// video_sharpen: horizontal unsharp mask, fixed 3-clock latency (en only selects the result).
// out = c + 0.75*(c - (l+r)/2), per channel, clamped; only inside the video window.
// ---------------------------------------------------------------------------
module video_sharpen (
    input  wire        clk,
    input  wire        rst_n,
    input  wire        en,
    input  wire        in_vs,
    input  wire        in_hs,
    input  wire        in_de,
    input  wire        in_win,
    input  wire [23:0] in_rgb,
    output reg         out_vs,
    output reg         out_hs,
    output reg         out_de,
    output reg         out_win,
    output reg  [23:0] out_rgb
);
    reg [23:0] r0, r1, r2;
    reg        w0, w1, w2;
    reg        vs1, hs1, de1, vs2, hs2, de2;

    function [7:0] sh;
        input [7:0] l;
        input [7:0] c;
        input [7:0] r;
        reg signed [11:0] d;
        reg signed [11:0] e;
        reg signed [11:0] o;
        begin
            d = $signed({4'b0000, c}) + $signed({4'b0000, c}) - $signed({4'b0000, l}) - $signed({4'b0000, r});
            e = (d * 3) >>> 3;
            o = $signed({4'b0000, c}) + e;
            if (o < 0)        sh = 8'd0;
            else if (o > 255) sh = 8'd255;
            else              sh = o[7:0];
        end
    endfunction

    wire use_sh = en && w0 && w1 && w2;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            r0 <= 24'd0; r1 <= 24'd0; r2 <= 24'd0;
            w0 <= 1'b0;  w1 <= 1'b0;  w2 <= 1'b0;
            vs1 <= 1'b0; hs1 <= 1'b0; de1 <= 1'b0;
            vs2 <= 1'b0; hs2 <= 1'b0; de2 <= 1'b0;
            out_vs <= 1'b0; out_hs <= 1'b0; out_de <= 1'b0; out_win <= 1'b0;
            out_rgb <= 24'd0;
        end else begin
            r0 <= in_rgb; r1 <= r0; r2 <= r1;
            w0 <= in_win; w1 <= w0; w2 <= w1;
            vs1 <= in_vs; hs1 <= in_hs; de1 <= in_de;
            vs2 <= vs1;   hs2 <= hs1;   de2 <= de1;
            out_vs <= vs2; out_hs <= hs2; out_de <= de2;
            out_win <= w1;
            if (use_sh)
                out_rgb <= {sh(r2[23:16], r1[23:16], r0[23:16]),
                            sh(r2[15:8],  r1[15:8],  r0[15:8]),
                            sh(r2[7:0],   r1[7:0],   r0[7:0])};
            else
                out_rgb <= r1;
        end
    end
endmodule


// ----------------------------------------------------------------------------
// Focus (sharpness) meter (Tenengrad).  Sums the SQUARED Sobel gradient over the image window for one frame
// (gradients below NOISE are ignored; m = min(mag,1023)/8, term = m*m).  The squared form is used because the plain
// sum of |gradient| does not change when an edge is blurred, the sum of squares does.  At the next vsync:
//   score = sum / 262144 (clipped to 9999)  - an absolute sharpness number
//   bar   = score relative to a slowly decaying peak (0..127), so turning the lens until the bar is full = best focus
// The restoring division is sequential (8 clocks); upd pulses when score / bar are updated.
// ----------------------------------------------------------------------------
module focus_meter #(
    parameter integer NOISE = 16,
    parameter integer PEAK_MIN = 64
)(
    input  wire        clk,
    input  wire        rst_n,
    input  wire        in_vs,
    input  wire [10:0] mag,
    input  wire        mag_v,
    output reg  [13:0] score,
    output reg  [6:0]  bar,
    output reg         upd
);
    reg        vs_d;
    reg [39:0] sum;
    reg [15:0] s;
    reg [15:0] peak;
    reg [16:0] rem;
    reg [7:0]  quo;
    reg [3:0]  it;
    reg [2:0]  st;
    reg [16:0] rem2;
    wire [9:0] mcl = (mag > 11'd1023) ? 10'd1023 : mag[9:0];
    wire [6:0] mc  = mcl[9:3];
    wire [13:0] sq = mc * mc;
    wire       add = mag_v && (mag >= NOISE);
    wire [15:0] peak_dec = peak - {8'd0, peak[15:8]};

    always @(posedge clk or negedge rst_n) begin
        if(!rst_n) begin
            vs_d <= 1'b0; sum <= 40'd0; s <= 16'd0; peak <= PEAK_MIN; rem <= 17'd0; quo <= 8'd0; it <= 4'd0; st <= 3'd0;
            score <= 14'd0; bar <= 7'd0; upd <= 1'b0;
        end
        else begin
            vs_d <= in_vs;
            upd  <= 1'b0;
            if(in_vs && !vs_d) begin
                s   <= sum[33:18];
                sum <= 40'd0;
                st  <= 3'd1;
            end
            else if(add)
                sum <= sum + {26'd0, sq};

            case(st)
                3'd1: begin
                    if(s > peak)                 peak <= s;
                    else if(peak_dec > PEAK_MIN) peak <= (peak_dec > s) ? peak_dec : s;
                    else                         peak <= (s > PEAK_MIN) ? s : PEAK_MIN;
                    st <= 3'd2;
                end
                3'd2: begin
                    rem <= {1'b0, s};
                    quo <= 8'd0;
                    it  <= 4'd0;
                    st  <= 3'd3;
                end
                3'd3: begin
                    rem2 = {rem[15:0], 1'b0};
                    if(rem2 >= {1'b0, peak}) begin
                        rem <= rem2 - {1'b0, peak};
                        quo <= {quo[6:0], 1'b1};
                    end
                    else begin
                        rem <= rem2;
                        quo <= {quo[6:0], 1'b0};
                    end
                    it <= it + 4'd1;
                    if(it == 4'd7) st <= 3'd4;
                end
                3'd4: begin
                    score <= (s > 16'd9999) ? 14'd9999 : s[13:0];
                    bar   <= quo[7:1];
                    upd   <= 1'b1;
                    st    <= 3'd0;
                end
                default: ;
            endcase
        end
    end
endmodule
